// =============================================================================
// Section A: synthetic-seed comparator/ranking sweep.
// =============================================================================

fn seed_from_json(value: &Value) -> IntrinsicPeriodicSeed {
    let exact_envelope = match &value["exact"] {
        Value::Null => None,
        exact => Some(IntrinsicPeriodicExactEnvelope {
            maximum_side_grid: decode_f64_bits(exact, "maximumSideGrid"),
            area_grid2: exact["areaGrid2"]
                .as_str()
                .expect("areaGrid2 present")
                .to_string(),
            span_grid: decode_f64_bits(exact, "spanGrid"),
        }),
    };
    let canonical_key = value["canonicalKey"]
        .as_str()
        .expect("canonicalKey present")
        .to_string();
    IntrinsicPeriodicSeed {
        role: IntrinsicPeriodicRole::P1,
        cell_key: format!("cell-{canonical_key}"),
        placements: Vec::new(),
        remaining_family_members: Vec::new(),
        component_count: decode_f64_bits(value, "componentCount"),
        isolated_piece_count: decode_f64_bits(value, "isolatedPieceCount"),
        largest_component_size: decode_f64_bits(value, "largestComponentSize"),
        maximum_side_mm: decode_f64_bits(value, "maximumSideMm"),
        envelope_area_mm2: decode_f64_bits(value, "envelopeAreaMm2"),
        envelope_span_mm: decode_f64_bits(value, "envelopeSpanMm"),
        exact_envelope,
        crop: IntrinsicPeriodicCropProvenance {
            rows: 1.0,
            columns: 1.0,
            traversal: IntrinsicPeriodicCropTraversal::Row,
            corner: 0,
        },
        canonical_key,
    }
}

#[test]
fn seed_battery_cases_reproduce_ts_outcomes() {
    let vectors = load_vectors();
    let cases = vectors["seedBatteryCases"]
        .as_array()
        .expect("seedBatteryCases present");
    assert!(!cases.is_empty());

    for case in cases {
        let case_id = case["caseId"].as_str().expect("caseId present");
        let seeds: Vec<IntrinsicPeriodicSeed> = case["seeds"]
            .as_array()
            .expect("seeds array present")
            .iter()
            .map(seed_from_json)
            .collect();

        let mut compare_envelope_signs = Vec::new();
        let mut compare_envelope_area_first_signs = Vec::new();
        for first in &seeds {
            for second in &seeds {
                compare_envelope_signs
                    .push(compare_intrinsic_periodic_seed_envelope(first, second) as i64);
                compare_envelope_area_first_signs.push(
                    compare_intrinsic_periodic_seed_envelope_area_first(first, second) as i64,
                );
            }
        }
        let expected_envelope_signs: Vec<i64> = case["compareEnvelopeSigns"]
            .as_array()
            .expect("compareEnvelopeSigns present")
            .iter()
            .map(|v| v.as_i64().expect("sign is an integer"))
            .collect();
        let expected_envelope_area_first_signs: Vec<i64> = case["compareEnvelopeAreaFirstSigns"]
            .as_array()
            .expect("compareEnvelopeAreaFirstSigns present")
            .iter()
            .map(|v| v.as_i64().expect("sign is an integer"))
            .collect();
        assert_eq!(
            compare_envelope_signs, expected_envelope_signs,
            "{case_id}: compareIntrinsicPeriodicSeedEnvelope signs"
        );
        assert_eq!(
            compare_envelope_area_first_signs, expected_envelope_area_first_signs,
            "{case_id}: compareIntrinsicPeriodicSeedEnvelopeAreaFirst signs"
        );

        let ranked: Vec<String> = rank_intrinsic_periodic_seeds(seeds.clone())
            .into_iter()
            .map(|s| s.canonical_key)
            .collect();
        let expected_ranked: Vec<String> = case["rankedCanonicalKeys"]
            .as_array()
            .expect("rankedCanonicalKeys present")
            .iter()
            .map(|v| v.as_str().expect("string").to_string())
            .collect();
        assert_eq!(
            ranked, expected_ranked,
            "{case_id}: rankIntrinsicPeriodicSeeds"
        );

        let non_dominated: Vec<String> = non_dominated_intrinsic_periodic_seeds(seeds.clone())
            .into_iter()
            .map(|s| s.canonical_key)
            .collect();
        let expected_non_dominated: Vec<String> = case["nonDominatedCanonicalKeys"]
            .as_array()
            .expect("nonDominatedCanonicalKeys present")
            .iter()
            .map(|v| v.as_str().expect("string").to_string())
            .collect();
        assert_eq!(
            non_dominated, expected_non_dominated,
            "{case_id}: nonDominatedIntrinsicPeriodicSeeds"
        );

        let front: Vec<String> = select_intrinsic_periodic_seed_front(seeds.clone(), 2)
            .into_iter()
            .map(|s| s.canonical_key)
            .collect();
        let expected_front: Vec<String> = case["frontCanonicalKeys"]
            .as_array()
            .expect("frontCanonicalKeys present")
            .iter()
            .map(|v| v.as_str().expect("string").to_string())
            .collect();
        assert_eq!(
            front, expected_front,
            "{case_id}: selectIntrinsicPeriodicSeedFront"
        );
    }
}

// =============================================================================
// Section B: continuation-execution-ordering + phase-residual pure sweep.
// =============================================================================

/// Only `.len()` of a seed's `placements` array is ever observed by the
/// pure functions this section exercises (execution ordering, never
/// geometry) -- see `synthetic_continuation`'s own doc note -- so this
/// placeholder's field values are otherwise arbitrary.
fn dummy_placed_piece() -> IrregularPlacedPiece {
    let piece_id = PieceId::new("dummy");
    let polygon = IrregularPolygon::new(vec![
        IrregularPoint::new(0.0, 0.0),
        IrregularPoint::new(1.0, 0.0),
        IrregularPoint::new(1.0, 1.0),
        IrregularPoint::new(0.0, 1.0),
    ]);
    IrregularPlacedPiece {
        placement: IrregularPlacement {
            piece_id: Some(piece_id.clone()),
            source_piece_id: piece_id.clone(),
            placement_reference: None,
            transform: IrregularTransform {
                translate_x: 0.0,
                translate_y: 0.0,
                rotation_deg: 0.0,
                mirrored: false,
            },
        },
        collision_geometry: TransformedCollisionGeometry {
            source_piece_id: piece_id,
            transform: IrregularTransformCandidate {
                index: 0.0,
                rotation_deg: 0.0,
                mirrored: false,
                reason: IrregularTransformReason::Configured,
            },
            polygon: polygon.clone(),
            bounds: bounds_of(&polygon.points),
        },
    }
}

fn synthetic_continuation(entry: &Value) -> IntrinsicPeriodicContinuation {
    let source_id = entry["sourceId"]
        .as_str()
        .expect("sourceId present")
        .to_string();
    let placement_count = entry["placementCount"]
        .as_u64()
        .expect("placementCount present") as usize;
    let seed = IntrinsicPeriodicSeed {
        role: IntrinsicPeriodicRole::P1,
        cell_key: format!("cell-{source_id}"),
        // Every entry carries a matching `exact` envelope (mirroring
        // `dump-periodic.ts`'s `syntheticContinuation`) so
        // `compareIntrinsicPeriodicSeedEnvelopeAreaFirst`'s
        // `exactEnvelopeForSeed` short-circuits on its first tier without
        // ever reading `placements` -- this section exercises
        // execution-ordering only.
        placements: (0..placement_count).map(|_| dummy_placed_piece()).collect(),
        remaining_family_members: Vec::new(),
        component_count: 1.0,
        isolated_piece_count: 0.0,
        largest_component_size: placement_count as f64,
        maximum_side_mm: decode_f64_bits(entry, "maximumSideMm"),
        envelope_area_mm2: decode_f64_bits(entry, "envelopeAreaMm2"),
        envelope_span_mm: decode_f64_bits(entry, "envelopeSpanMm"),
        exact_envelope: Some(IntrinsicPeriodicExactEnvelope {
            maximum_side_grid: decode_f64_bits(entry, "maximumSideMm") * 1000.0,
            area_grid2: format!(
                "{}",
                (decode_f64_bits(entry, "envelopeAreaMm2") * 1_000_000.0).round() as i64
            ),
            span_grid: decode_f64_bits(entry, "envelopeSpanMm") * 1000.0,
        }),
        crop: IntrinsicPeriodicCropProvenance {
            rows: 1.0,
            columns: 1.0,
            traversal: IntrinsicPeriodicCropTraversal::Row,
            corner: 0,
        },
        canonical_key: source_id.clone(),
    };
    IntrinsicPeriodicContinuation {
        source_id: source_id.clone(),
        role: IntrinsicPeriodicRole::P1,
        family_key: "family".to_string(),
        cell_key: seed.cell_key.clone(),
        basis_source_key: None,
        seed,
    }
}

#[test]
fn continuation_ordering_cases_reproduce_ts_outcomes() {
    let vectors = load_vectors();
    let cases = vectors["continuationOrderingCases"]
        .as_array()
        .expect("continuationOrderingCases present");
    assert!(!cases.is_empty());

    for case in cases {
        let case_id = case["caseId"].as_str().expect("caseId present");
        let continuations: Vec<IntrinsicPeriodicContinuation> = case["entries"]
            .as_array()
            .expect("entries array present")
            .iter()
            .map(synthetic_continuation)
            .collect();

        let ordered: Vec<String> = order_periodic_continuations_for_execution(&continuations)
            .into_iter()
            .map(|c| c.source_id)
            .collect();
        let expected_ordered: Vec<String> = case["orderedSourceIds"]
            .as_array()
            .expect("orderedSourceIds present")
            .iter()
            .map(|v| v.as_str().expect("string").to_string())
            .collect();
        assert_eq!(
            ordered, expected_ordered,
            "{case_id}: orderPeriodicContinuationsForExecution"
        );

        let capped: Vec<String> = continuations_for_execution(continuations.clone(), Some(1000.0))
            .into_iter()
            .map(|c| c.source_id)
            .collect();
        let expected_capped: Vec<String> = case["forExecutionCappedSourceIds"]
            .as_array()
            .expect("forExecutionCappedSourceIds present")
            .iter()
            .map(|v| v.as_str().expect("string").to_string())
            .collect();
        assert_eq!(
            capped, expected_capped,
            "{case_id}: continuationsForExecution(capped)"
        );

        let uncapped: Vec<String> = continuations_for_execution(continuations.clone(), None)
            .into_iter()
            .map(|c| c.source_id)
            .collect();
        let expected_uncapped: Vec<String> = case["forExecutionUncappedSourceIds"]
            .as_array()
            .expect("forExecutionUncappedSourceIds present")
            .iter()
            .map(|v| v.as_str().expect("string").to_string())
            .collect();
        assert_eq!(
            uncapped, expected_uncapped,
            "{case_id}: continuationsForExecution(uncapped)"
        );
    }
}

#[test]
fn phase_residual_cases_reproduce_ts_outcomes() {
    let vectors = load_vectors();
    let cases = vectors["phaseResidualCases"]
        .as_array()
        .expect("phaseResidualCases present");
    assert!(!cases.is_empty());
    for case in cases {
        let total_ms = decode_f64_bits(case, "totalMs");
        let residual_ms = decode_f64_bits(case, "residualMs");
        let expected = case["complete"].as_bool().expect("complete present");
        assert_eq!(
            phase_residual_coverage_complete(total_ms, residual_ms),
            expected,
            "phaseResidualCoverageComplete({total_ms}, {residual_ms})"
        );
    }
}

// =============================================================================
// Section C: `enumerateIntrinsicPeriodicCells` end-to-end catalog cases.
// =============================================================================

fn catalog_options_for_sweep(label: &str) -> IntrinsicPeriodicCatalogOptions {
    let (maximum_cells_per_family_role, capture_source_survival_audit) = match label {
        "default" => (4, false),
        "audit" => (4, true),
        "narrow-front" => (1, false),
        "wide-front" => (16, true),
        other => panic!("unknown catalog sweep label {other}"),
    };
    IntrinsicPeriodicCatalogOptions {
        maximum_runtime_ms: 15_000.0,
        maximum_family_count: 8,
        maximum_transforms_per_family: 16,
        maximum_pairs_per_family: 120,
        maximum_cells_per_family_role,
        capture_source_survival_audit,
    }
}

#[test]
fn catalog_cases_reproduce_ts_outcomes() {
    let vectors = load_vectors();
    let cases = vectors["catalogCases"]
        .as_array()
        .expect("catalogCases present");
    assert!(!cases.is_empty());
    let settings = settings();

    for case in cases {
        let case_id = case["caseId"].as_str().expect("caseId present");
        let pieces = prepared_pieces_from_json(&case["pieces"]);
        let sweep_label = case["sweepLabel"].as_str().expect("sweepLabel present");
        let options = catalog_options_for_sweep(sweep_label);

        let mut geometry_cache = GeometryCacheStore::new();
        let mut ctx = PeriodicRunContext {
            settings: &settings,
            geometry_cache: &mut geometry_cache,
            control: None,
        };
        let catalog = enumerate_intrinsic_periodic_cells(&pieces, &options, &mut ctx)
            .unwrap_or_else(|err| {
                panic!("{case_id}: enumerate_intrinsic_periodic_cells failed: {err:?}")
            });

        let expected = &case["catalog"];
        assert_eq!(
            catalog.family_coverage_complete,
            expected["familyCoverageComplete"].as_bool().unwrap(),
            "{case_id}: familyCoverageComplete"
        );
        assert_eq!(
            catalog.runtime_coverage_complete,
            expected["runtimeCoverageComplete"].as_bool().unwrap(),
            "{case_id}: runtimeCoverageComplete"
        );
        let expected_selected_family_key =
            expected["selectedFamilyKey"].as_str().map(str::to_string);
        assert_eq!(
            catalog.selected_family_key, expected_selected_family_key,
            "{case_id}: selectedFamilyKey"
        );
        assert_eq!(
            catalog.cells.len(),
            expected["cellCount"].as_u64().unwrap() as usize,
            "{case_id}: cells.len"
        );

        let expected_families = expected["families"].as_array().expect("families present");
        assert_eq!(
            catalog.families.len(),
            expected_families.len(),
            "{case_id}: families.len"
        );
        for (index, (family, expected_family)) in catalog
            .families
            .iter()
            .zip(expected_families.iter())
            .enumerate()
        {
            let label = format!("{case_id}.families[{index}]");
            assert_eq!(
                family.family_key,
                expected_family["familyKey"].as_str().unwrap(),
                "{label}.familyKey"
            );
            assert_f64_bits_eq(
                family.member_count,
                decode_f64_bits(expected_family, "memberCount"),
                &format!("{label}.memberCount"),
            );
            assert_f64_bits_eq(
                family.retained_transform_count,
                decode_f64_bits(expected_family, "retainedTransformCount"),
                &format!("{label}.retainedTransformCount"),
            );
            assert_eq!(
                family.transform_coverage_complete,
                expected_family["transformCoverageComplete"]
                    .as_bool()
                    .unwrap(),
                "{label}.transformCoverageComplete"
            );
            assert_f64_bits_eq(
                family.enumerated_pair_count,
                decode_f64_bits(expected_family, "enumeratedPairCount"),
                &format!("{label}.enumeratedPairCount"),
            );
            assert_eq!(
                family.pair_coverage_complete,
                expected_family["pairCoverageComplete"].as_bool().unwrap(),
                "{label}.pairCoverageComplete"
            );
            assert_eq!(
                family.cell_coverage_complete,
                expected_family["cellCoverageComplete"].as_bool().unwrap(),
                "{label}.cellCoverageComplete"
            );

            let expected_cells = expected_family["cells"].as_array().expect("cells present");
            assert_eq!(
                family.cells.len(),
                expected_cells.len(),
                "{label}.cells.len"
            );
            for (cell_index, (cell, expected_cell)) in
                family.cells.iter().zip(expected_cells.iter()).enumerate()
            {
                let cell_label = format!("{label}.cells[{cell_index}]");
                assert_eq!(
                    ts_literal(&cell.role),
                    expected_cell["role"].as_str().unwrap(),
                    "{cell_label}.role"
                );
                assert_eq!(
                    cell.determinant_grid2,
                    expected_cell["determinantGrid2"].as_str().unwrap(),
                    "{cell_label}.determinantGrid2"
                );
                assert_eq!(
                    cell.member_doubled_area_grid2,
                    expected_cell["memberDoubledAreaGrid2"].as_str().unwrap(),
                    "{cell_label}.memberDoubledAreaGrid2"
                );
                assert_f64_bits_eq(
                    cell.envelope_maximum_side_mm,
                    decode_f64_bits(expected_cell, "envelopeMaximumSideMm"),
                    &format!("{cell_label}.envelopeMaximumSideMm"),
                );
                assert_f64_bits_eq(
                    cell.hull_waste_ratio,
                    decode_f64_bits(expected_cell, "hullWasteRatio"),
                    &format!("{cell_label}.hullWasteRatio"),
                );
                assert_f64_bits_eq(
                    cell.shared_boundary_length_mm,
                    decode_f64_bits(expected_cell, "sharedBoundaryLengthMm"),
                    &format!("{cell_label}.sharedBoundaryLengthMm"),
                );
                assert_eq!(
                    cell.infinite_far_proof,
                    expected_cell["infiniteFarProof"].as_bool().unwrap(),
                    "{cell_label}.infiniteFarProof"
                );
                assert_eq!(
                    cell.three_by_three_lattice_legal,
                    expected_cell["threeByThreeLatticeLegal"].as_bool().unwrap(),
                    "{cell_label}.threeByThreeLatticeLegal"
                );
                assert_eq!(
                    cell.three_by_three_centre_contact_complete,
                    expected_cell["threeByThreeCentreContactComplete"]
                        .as_bool()
                        .unwrap(),
                    "{cell_label}.threeByThreeCentreContactComplete"
                );
                let actual_kind = cell
                    .basis_provenance
                    .as_ref()
                    .map(|p| ts_literal(&p.source_kind));
                let expected_kind = expected_cell["basisSourceKind"]
                    .as_str()
                    .map(str::to_string);
                assert_eq!(actual_kind, expected_kind, "{cell_label}.basisSourceKind");
                let actual_key = cell.basis_provenance.as_ref().map(|p| p.source_key.clone());
                let expected_key = expected_cell["basisSourceKey"].as_str().map(str::to_string);
                assert_eq!(actual_key, expected_key, "{cell_label}.basisSourceKey");
                assert_eq!(
                    cell.canonical_key,
                    expected_cell["canonicalKey"].as_str().unwrap(),
                    "{cell_label}.canonicalKey"
                );
            }
        }

        // TS `catalog.rejected: Readonly<Record<string, number>>`
        // (`CELLS:147`) -- a plain JS object built via `Object.fromEntries`
        // over already-`.toSorted()`-ordered entries (characterization doc
        // §5 item 10). Compared here as a sorted-by-key set (not
        // positionally): a plain-object's keys are always distinct, so
        // alphabetical-by-key order (what `serde_json`'s default
        // `BTreeMap`-backed `Value::Object` iteration yields) is always
        // identical to TS's own bare-`.toSorted()`-of-the-stringified-pair
        // order whenever every key is unique, which a `Map`'s keys always
        // are by construction.
        let mut expected_rejected: Vec<(String, f64)> = expected["rejected"]
            .as_object()
            .expect("rejected present")
            .iter()
            .map(|(key, count)| (key.clone(), count.as_f64().expect("rejected count")))
            .collect();
        expected_rejected.sort_by(|(first, _), (second, _)| first.cmp(second));
        let mut actual_rejected = catalog.rejected.clone();
        actual_rejected.sort_by(|(first, _), (second, _)| first.cmp(second));
        assert_eq!(actual_rejected, expected_rejected, "{case_id}: rejected");
    }
}

// =============================================================================
// Section D: `runIntrinsicPeriodicFamilyPortfolio` end-to-end cases.
// =============================================================================

fn portfolio_options_for_case(case: &Value) -> IntrinsicPeriodicFamilyPortfolioOptions<'static> {
    let label = case["sweepLabel"].as_str().expect("sweepLabel present");
    let mut options = IntrinsicPeriodicFamilyPortfolioOptions::default();
    match label {
        "default" => {
            options.maximum_continuation_count = 8;
            options.maximum_continuation_candidate_evaluations = Some(200.0);
        }
        "small-cap" => {
            options.maximum_continuation_count = 2;
            options.maximum_continuation_candidate_evaluations = Some(50.0);
        }
        "audit-admit" => {
            options.maximum_continuation_count = 8;
            options.maximum_continuation_candidate_evaluations = Some(200.0);
            options.capture_source_survival_audit = true;
            options.admit_source_audit_witnesses = true;
        }
        "audit-p2-axis-union" => {
            options.maximum_continuation_count = 8;
            options.maximum_continuation_candidate_evaluations = Some(200.0);
            options.capture_source_survival_audit = true;
            options.admit_source_audit_witnesses = true;
            options.source_audit_scope = IntrinsicPeriodicSourceAuditScope::P2AxisUnion;
        }
        "global-deadline" => {
            options.maximum_continuation_count = 8;
            options.maximum_continuation_candidate_evaluations = Some(200.0);
            options.maximum_total_runtime_ms = 0.0;
        }
        "uncapped-evaluations" => {
            options.maximum_continuation_count = 8;
        }
        "single-continuation" => {
            options.maximum_continuation_count = 1;
            options.maximum_continuation_candidate_evaluations = Some(200.0);
        }
        "audit-all-scope" => {
            options.maximum_continuation_count = 8;
            options.maximum_continuation_candidate_evaluations = Some(200.0);
            options.capture_source_survival_audit = true;
            options.admit_source_audit_witnesses = false;
            options.source_audit_scope = IntrinsicPeriodicSourceAuditScope::All;
        }
        "many-crops" => {
            options.maximum_continuation_count = 8;
            options.maximum_continuation_candidate_evaluations = Some(200.0);
            options.maximum_crops_per_cell = 8;
        }
        "basis-source-key-filtered" => {
            options.maximum_continuation_count = 8;
            options.maximum_continuation_candidate_evaluations = Some(200.0);
            options.basis_source_key = Some(
                case["basisSourceKey"]
                    .as_str()
                    .expect("basisSourceKey present")
                    .to_string(),
            );
        }
        other => panic!("unknown portfolio sweep label {other}"),
    }
    options
}

#[test]
fn portfolio_cases_reproduce_ts_outcomes() {
    let vectors = load_vectors();
    let cases = vectors["portfolioCases"]
        .as_array()
        .expect("portfolioCases present");
    assert!(!cases.is_empty());
    let settings = settings();
    let archive_sheet = SheetSpec {
        width: 2000.0,
        height: 2000.0,
        label: "periodic-vectors".to_string(),
    };

    for case in cases {
        let case_id = case["caseId"].as_str().expect("caseId present");
        let pieces = prepared_pieces_from_json(&case["pieces"]);
        let options = portfolio_options_for_case(case);

        let mut geometry_cache = GeometryCacheStore::new();
        let result = run_intrinsic_periodic_family_portfolio(
            &archive_sheet,
            &pieces,
            options,
            &settings,
            &mut geometry_cache,
        )
        .unwrap_or_else(|err| {
            panic!("{case_id}: run_intrinsic_periodic_family_portfolio failed: {err:?}")
        });

        let expected = &case["result"];
        assert_eq!(
            result.catalog.families.len(),
            expected["catalogFamilyCount"].as_u64().unwrap() as usize,
            "{case_id}: catalog.families.len"
        );

        let expected_continuations = expected["continuations"]
            .as_array()
            .expect("continuations present");
        assert_eq!(
            result.continuations.len(),
            expected_continuations.len(),
            "{case_id}: continuations.len"
        );
        for (index, (continuation, expected_continuation)) in result
            .continuations
            .iter()
            .zip(expected_continuations.iter())
            .enumerate()
        {
            let label = format!("{case_id}.continuations[{index}]");
            assert_eq!(
                continuation.source_id,
                expected_continuation["sourceId"].as_str().unwrap(),
                "{label}.sourceId"
            );
            assert_eq!(
                ts_literal(&continuation.role),
                expected_continuation["role"].as_str().unwrap(),
                "{label}.role"
            );
            assert_eq!(
                continuation.family_key,
                expected_continuation["familyKey"].as_str().unwrap(),
                "{label}.familyKey"
            );
            assert_eq!(
                continuation.cell_key,
                expected_continuation["cellKey"].as_str().unwrap(),
                "{label}.cellKey"
            );
            assert_eq!(
                continuation.basis_source_key.as_deref(),
                expected_continuation["basisSourceKey"].as_str(),
                "{label}.basisSourceKey"
            );
            assert_f64_bits_eq(
                continuation.seed.placements.len() as f64,
                decode_f64_bits(expected_continuation, "placementCount"),
                &format!("{label}.placementCount"),
            );
            assert_eq!(
                continuation.seed.canonical_key,
                expected_continuation["canonicalKey"].as_str().unwrap(),
                "{label}.canonicalKey"
            );
        }

        let expected_omissions = expected["continuationOmissions"]
            .as_array()
            .expect("continuationOmissions present");
        assert_eq!(
            result.continuation_omissions.len(),
            expected_omissions.len(),
            "{case_id}: continuationOmissions.len"
        );
        for (index, (omission, expected_omission)) in result
            .continuation_omissions
            .iter()
            .zip(expected_omissions.iter())
            .enumerate()
        {
            let label = format!("{case_id}.continuationOmissions[{index}]");
            assert_eq!(
                omission.source_id,
                expected_omission["sourceId"].as_str().unwrap(),
                "{label}.sourceId"
            );
            assert_eq!(
                ts_literal(&omission.reason),
                expected_omission["reason"].as_str().unwrap(),
                "{label}.reason"
            );
        }

        assert_eq!(
            result.continuation_coverage_complete,
            expected["continuationCoverageComplete"].as_bool().unwrap(),
            "{case_id}: continuationCoverageComplete"
        );
        assert_eq!(
            result.continuation_execution_coverage_complete,
            expected["continuationExecutionCoverageComplete"]
                .as_bool()
                .unwrap(),
            "{case_id}: continuationExecutionCoverageComplete"
        );
        assert_eq!(
            result.continuation_budget_settlement_complete,
            expected["continuationBudgetSettlementComplete"]
                .as_bool()
                .unwrap(),
            "{case_id}: continuationBudgetSettlementComplete"
        );

        let expected_survival = expected["sourceCropSurvival"]
            .as_array()
            .expect("sourceCropSurvival present");
        assert_eq!(
            result.source_crop_survival.len(),
            expected_survival.len(),
            "{case_id}: sourceCropSurvival.len"
        );
        for (index, (survival, expected_entry)) in result
            .source_crop_survival
            .iter()
            .zip(expected_survival.iter())
            .enumerate()
        {
            let label = format!("{case_id}.sourceCropSurvival[{index}]");
            assert_eq!(
                ts_literal(&survival.role),
                expected_entry["role"].as_str().unwrap(),
                "{label}.role"
            );
            assert_eq!(
                survival.source_key,
                expected_entry["sourceKey"].as_str().unwrap(),
                "{label}.sourceKey"
            );
            assert_eq!(
                ts_literal(&survival.source_kind),
                expected_entry["sourceKind"].as_str().unwrap(),
                "{label}.sourceKind"
            );
            assert_f64_bits_eq(
                survival.retained_cell_count,
                decode_f64_bits(expected_entry, "retainedCellCount"),
                &format!("{label}.retainedCellCount"),
            );
            assert_f64_bits_eq(
                survival.direct_valid_crop_count_before_front,
                decode_f64_bits(expected_entry, "directValidCropCountBeforeFront"),
                &format!("{label}.directValidCropCountBeforeFront"),
            );
            assert_f64_bits_eq(
                survival.direct_valid_crop_count,
                decode_f64_bits(expected_entry, "directValidCropCount"),
                &format!("{label}.directValidCropCount"),
            );
            assert_f64_bits_eq(
                survival.crop_front_count,
                decode_f64_bits(expected_entry, "cropFrontCount"),
                &format!("{label}.cropFrontCount"),
            );
            assert_f64_bits_eq(
                survival.unique_seed_count,
                decode_f64_bits(expected_entry, "uniqueSeedCount"),
                &format!("{label}.uniqueSeedCount"),
            );
            assert_f64_bits_eq(
                survival.selected_continuation_count,
                decode_f64_bits(expected_entry, "selectedContinuationCount"),
                &format!("{label}.selectedContinuationCount"),
            );
        }

        assert_eq!(
            result.source_audit_witnesses.len(),
            expected["sourceAuditWitnessCount"].as_u64().unwrap() as usize,
            "{case_id}: sourceAuditWitnesses.len"
        );
        let actual_witness_ids: Vec<String> = result
            .source_audit_witnesses
            .iter()
            .map(|w| format!("{}:{}:{}", ts_literal(&w.role), w.source_key, w.cell_key))
            .collect();
        let expected_witness_ids: Vec<String> = expected["sourceAuditWitnessSourceIds"]
            .as_array()
            .expect("sourceAuditWitnessSourceIds present")
            .iter()
            .map(|v| v.as_str().expect("string").to_string())
            .collect();
        assert_eq!(
            actual_witness_ids, expected_witness_ids,
            "{case_id}: sourceAuditWitnesses identities"
        );

        assert_f64_bits_eq(
            result.source_audit_non_dominated_crop_count,
            decode_f64_bits(expected, "sourceAuditNonDominatedCropCount"),
            &format!("{case_id}.sourceAuditNonDominatedCropCount"),
        );
        assert_eq!(
            result.source_audit_replay_accepted,
            expected["sourceAuditReplayAccepted"].as_bool().unwrap(),
            "{case_id}: sourceAuditReplayAccepted"
        );

        let expected_run_statuses = expected["runStatuses"]
            .as_array()
            .expect("runStatuses present");
        assert_eq!(
            result.runs.len(),
            expected_run_statuses.len(),
            "{case_id}: runs.len"
        );
        for (index, (run, expected_run)) in result
            .runs
            .iter()
            .zip(expected_run_statuses.iter())
            .enumerate()
        {
            let label = format!("{case_id}.runStatuses[{index}]");
            assert_eq!(
                run.continuation.source_id,
                expected_run["sourceId"].as_str().unwrap(),
                "{label}.sourceId"
            );
            assert_eq!(
                ts_literal(&run.status),
                expected_run["status"].as_str().unwrap(),
                "{label}.status"
            );
            let actual_hash = run
                .result
                .as_ref()
                .and_then(|r| r.metrics.as_ref())
                .map(|m| m.canonical_geometry_hash.clone());
            let expected_hash = expected_run["canonicalGeometryHash"]
                .as_str()
                .map(str::to_string);
            assert_eq!(actual_hash, expected_hash, "{label}.canonicalGeometryHash");
        }

        let actual_archive_hashes: Vec<String> = result
            .archive
            .iter()
            .map(|m| m.canonical_geometry_hash.clone())
            .collect();
        let expected_archive_hashes: Vec<String> = expected["archiveHashes"]
            .as_array()
            .expect("archiveHashes present")
            .iter()
            .map(|v| v.as_str().expect("string").to_string())
            .collect();
        assert_eq!(
            actual_archive_hashes, expected_archive_hashes,
            "{case_id}: archive hashes"
        );

        let actual_winner_source_id = result
            .winner
            .as_ref()
            .map(|w| w.continuation.source_id.clone());
        let expected_winner_source_id = expected["winnerSourceId"].as_str().map(str::to_string);
        assert_eq!(
            actual_winner_source_id, expected_winner_source_id,
            "{case_id}: winnerSourceId"
        );
    }
}

#[test]
fn vector_file_metadata_is_present() {
    let vectors = load_vectors();
    assert!(vectors["generatingCommit"].as_str().is_some());
    let total = vectors["totalVectorCount"]
        .as_u64()
        .expect("totalVectorCount present");
    assert!(total >= 300, "expected >= 300 total vectors, got {total}");
    let _ = HashMap::<String, String>::new(); // keep `HashMap` import used if sections above shrink
}
